package com.gsterling.press; import android.content.Context; import androidx.annotation.NonNull; import androidx.work.*; public class RotationWorker extends Worker{public RotationWorker(@NonNull Context c,@NonNull WorkerParameters p){super(c,p);}@NonNull public Result doWork(){Context c=getApplicationContext();if(!Prefs.rotation(c))return Result.success();int i=(Prefs.index(c)+1)%7;try{MainActivity.applyScene(c,i);Prefs.setIndex(c,i);Scheduler.schedule(c,Scheduler.Mode.DAILY);return Result.success();}catch(Exception e){return Result.retry();}}}